from concurrent.futures import (
    ProcessPoolExecutor)

daten = []

def merke(x):
    daten.append(x)

if __name__ == "__main__":
    with ProcessPoolExecutor(2) as ex:
        list(ex.map(merke, range(5)))
    print(len(daten))

def quelle():
    for i in range(2):
        print("lese", i)
        yield i

def doppelt(xs):
    for x in xs:
        print("verdopple", x)
        yield 2 * x

for w in doppelt(quelle()):
    print("ergebnis", w)
